class Pen {
	constructor(pos, col) {
		this.pos = pos;
		this.lpos = createVector(pos.x, pos.y);
		this.col = col;
		this.counter = 0;
		this.alive = true;
	}
	show() {
		this.counter += 1;
		if (this.counter > 150) this.alive = false;
		for (let i = 0; i < 20; i++) {
			this.pos.x += (0.5 - noise(this.pos.y / div)) * amp;
			this.pos.y += (0.5 - noise(this.pos.x / div)) * amp;
			paper.push();
			paper.translate(paper.width / 2, paper.height / 2);
			paper.stroke(this.col);
			paper.strokeWeight(4);
			paper.line(this.lpos.x, this.lpos.y, this.pos.x, this.pos.y);
			paper.pop();
			this.lpos.x = this.pos.x;
			this.lpos.y = this.pos.y;
		}
	}
}

