function makeBackground() {
	bg = createGraphics(width, height);
	for (let y = 0; y < bg.height; y += 0.1) {
		let x = random(width);
		bg.strokeWeight(1.5);
		bg.stroke(50 + 100 * noise(y / height));
		bg.line(0, y, x, y)
		bg.stroke(200 - 100 * noise(y / height));
		bg.line(x, y, width, y)
	}
}

function makeShadow() {
	shadow = createGraphics(width, height);
	shadow.translate(bg.width / 2, bg.height / 2);
	shadow.rotate(tilt);
	shadow.fill(0, 180);
	shadow.rectMode(CENTER);
	shadow.rect(5, 10, 0.9 * height * (11 / 8.5), 0.9 * height);
	shadow.filter(BLUR, 2)
